import React, { useState, useEffect } from 'react';
import { Button, Form, Container } from 'react-bootstrap';
import { useNavigate, useLocation } from 'react-router-dom';

const AuthForm = ({ setUser }) => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('user');
  const [isLogin, setIsLogin] = useState(true);
  const navigate = useNavigate();
  const location = useLocation();
  const from = location.state?.from?.pathname || '/';

  useEffect(() => {
    setEmail('');
    setPassword('');
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    const users = JSON.parse(localStorage.getItem('users')) || [];
    if (isLogin) {
      const user = users.find((user) => user.email === email && user.password === password);
      if (user) {
        localStorage.setItem('authToken', 'sample-token');
        localStorage.setItem('role', user.role);
        setUser({ email: user.email, role: user.role });
        if (user.role === 'admin') {
          navigate('/admin-dashboard');
        } else {
          navigate(from, { replace: true });
        }
      } else {
        alert('User not found. Please sign up.');
        setIsLogin(false);
      }
    } else {
      if (users.find((user) => user.email === email)) {
        alert('User already exists. Please log in.');
        setIsLogin(true);
      } else {
        const newUser = { email, password, role };
        users.push(newUser);
        localStorage.setItem('users', JSON.stringify(users));
        alert('Signup successful. Please log in.');
        setIsLogin(true);
      }
    }
  };

  const toggleMode = () => {
    setIsLogin(!isLogin);
    setEmail('');
    setPassword('');
  };

  return (
    <Container className="mt-4 auth-form-container">
      <h2 className="text-center">{isLogin ? 'Login' : 'Signup'}</h2>
      <Form onSubmit={handleSubmit} autoComplete="off">
        <Form.Group controlId="formBasicEmail" className="form-group">
          <Form.Label>Email address</Form.Label>
          <Form.Control
            type="email"
            placeholder="Enter email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
            name="email"
            autoComplete="new-email"
          />
        </Form.Group>

        <Form.Group controlId="formBasicPassword" className="form-group">
          <Form.Label>Password</Form.Label>
          <Form.Control
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
            name="password"
            autoComplete="new-password"
          />
        </Form.Group>

        {!isLogin && (
          <Form.Group controlId="formBasicRole" className="form-group">
            <Form.Label>Role</Form.Label>
            <Form.Control
              as="select"
              value={role}
              onChange={(e) => setRole(e.target.value)}
              required
            >
              <option value="user">User</option>
              <option value="admin">Admin</option>
            </Form.Control>
          </Form.Group>
        )}

        <Button variant="primary" type="submit" className="mt-3">
          {isLogin ? 'Login' : 'Signup'}
        </Button>
      </Form>
      <Button variant="link" onClick={toggleMode} className="mt-3">
        {isLogin ? 'Switch to Signup' : 'Switch to Login'}
      </Button>
    </Container>
  );
};

export default AuthForm;
